-//! cargo run -p theseus-mining -- --algo dynex --wallet DNX123...
-//!
-//! # Quai only (CPU mining)
-//! cargo run -p theseus-mining -- --algo quai
-//!
-//! # All miners simultaneously
-//! cargo run -p theseus-mining -- --algo all
