+    let d0 = info.dims[0];
+    let is_iq3_m = is_quantization_iq3_m(metadata.quantization());
+    match info.ggml_type {
+        GGML_TYPE_Q8_0 if d0.is_multiple_of(32) => Some(SynapseSelection {
