+// SPDX-License-Identifier: Apache-2.0 OR MIT
+//! GGUF header/metadata parsing and cursor helpers.
+
+use super::super::ggml::{
+    GGUF_MAGIC, GGUF_VALUE_TYPE_ARRAY, GGUF_VALUE_TYPE_BOOL, GGUF_VALUE_TYPE_FLOAT32,
