+            self.router.model_path()
+        );
+        if accelerator.synapse_signature() == Some(signature.as_str()) {
+            return Ok(true);
+        }
+        let weights = get_weights(&self.router, &tensor_name)
+            .map_err(|e| GpuError::MemoryError(format!("{label} dequantization failed: {e}")))?;
